import{d as r,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十七章","description":"《正易心法》第十七章——六十四卦，皆有取象：屯象草木、蒙象童稚……名义无不反对；不知取象与反对，是为学《易》之大病。","frontmatter":{"title":"正易心法·第十七章","description":"《正易心法》第十七章——六十四卦，皆有取象：屯象草木、蒙象童稚……名义无不反对；不知取象与反对，是为学《易》之大病。","category":"guide","aliases":["正易心法第十七章","六十四卦皆有取象","名义无不反对"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-17.md","filePath":"yijing/zheng-yi-xin-fa/chapter-17.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-17.md"},x=r({...c,setup(u){const i=[{id:"z17-01",label:"一、取象与名义反对",showLabel:!0,sentences:[["六十四卦，皆有",{text:"取象",glossary:"quxiang"},"。其为",{text:"名义",glossary:"mingyi"},"，无不反对。"]],note:["六十四卦都有取象，其卦名与含义无不构成反对关系。（这是第十六章「反对密意」的具体展开：前者说反对是圣人的密意，本章说六十四卦的**名义**无不反对——**结构（反对卦画）→ 象（取象物象）→ 义（名义反对），三个层次一贯。**）"]},{id:"z17-02",label:"二、易者象也",showLabel:!0,sentences:[["《易》之取象，世所知者数卦而已，如颐、如鼎、如噬嗑之类是。殊不知《易》者，象也，依物象以为训，古六十四卦皆有取象。"]],note:["《易》的取象，世人只知道几个卦，如颐（卦画像口）、鼎（卦画像鼎）、噬嗑（卦画像口中有物）之类。殊不知《易》就是象，依据具体物象来解释，古来六十四卦都有取象。（**「《易》者，象也」是本章的核心命题**：辞是用来说明象的，象才是本体。所以正确顺序是：先看卦画（象）→ 再看取象（物象）→ 再看卦辞（文字）。）"]},{id:"z17-03",label:"三、六十四卦皆有取象",showLabel:!0,sentences:[["如屯象草木，蒙象童稚，需象燕宾，讼象饮食，师象军阵，比象翼戴，家人象家正，睽象覆家，余卦尽然。"]],note:["比如：屯象草木初生，蒙象幼童蒙昧，需象宴请宾客，讼象饮食争讼，师象军队阵列，比象辅翼拥戴，家人象家道端正，睽象家道倾覆——其余各卦都是这样。（这些不是随意比喻，而是**从卦画结构直接读出来的**：屯☷☳上坎下震，震（动）在下如种子萌动，坎（险）在上如土壤压覆——故象草木破土之艰难。）"]},{id:"z17-04",label:"四、名义反对之例",showLabel:!0,sentences:[["一人诸卦，名义无不反对。如噬嗑以",{text:"贪饕",glossary:"tantao"},"，贲以节饰，履以蹈艰危，小畜以享尊富，临以出而治人，观以入而处己，丰以富盛，旅以困穷。"]],note:["将诸卦一一对应，卦名与含义无不构成反对关系：噬嗑象贪婪吞食，贲象节制文饰；履象踩踏艰危，小畜象享受尊富；临象出外治人，观象退入处己；丰象富足盛大，旅象困顿穷乏。（**每一对都是一放一收、一苦一乐、一出（入）一盛一衰**——卦名的反对，就是现实的反对。）"]},{id:"z17-05",label:"五、学易之大病",showLabel:!0,sentences:[["自余推之，其名义反对，无不然者，此学《易》之大",{text:"病",glossary:"dabing"},"也。"]],note:["从其余各卦推演，其名义的反对关系无不如此。**不知此理，正是学习《易》的大毛病。**（「大病」是全书对错误最重的定性之一——因为不知取象是**不知《易》是象**（根本错误），不知反对是**不知吉凶一体**（哲学错误），两个根本错误叠加，就成了「大病」。与第一章「不知落处，则玩占亦虚语」完全同调。）"]}],o=[{id:"quxiang",term:"取象",pinyin:"qǔ xiàng",meaning:"取用具体物象。每个卦名都有其对应的具体物象，非随意比喻，而是从卦画结构读出。"},{id:"mingyi",term:"名义",pinyin:"míng yì",meaning:"卦名与含义。六十四卦的名义无不构成反对关系。"},{id:"tantao",term:"贪饕",pinyin:"tān tāo",meaning:"贪食。饕是贪食之兽。噬嗑象口中有物强行咬合，故有贪婪之象。"},{id:"dabing",term:"大病",pinyin:"dà bìng",meaning:"根本性的错误。不知取象＝不知《易》是象；不知反对＝不知吉凶一体。两个根本错误叠加。"}];return(b,n)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第十七章" tabindex="-1">正易心法·第十七章 <a class="header-anchor" href="#正易心法·第十七章" aria-label="Permalink to &quot;正易心法·第十七章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第十六章「反对」理论的<strong>具体展开与应用</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十六章（理论）：反对是圣人密意；吉凶一体，代谢循环；八对体卦是造化枢机</span></span>
<span class="line"><span>第十七章（应用）：六十四卦皆有取象（具体物象）</span></span>
<span class="line"><span>               六十四卦名义皆反对（义理对立）</span></span>
<span class="line"><span>               两者合一：取象 + 反对 = 完整读卦法</span></span></code></pre></div><p><strong>核心命题</strong>：<strong>《易》就是象</strong>——六十四卦每一个都有具体的物象取义，而且每对卦的名义都构成反对关系。<strong>不知此二者，是学《易》的根本大病。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「《易》者，象也」的方法论地位</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《系辞传》：「圣人设卦观象，系辞焉而明吉凶」「象也者，像此者也」</span></span>
<span class="line"><span>麻衣的强调：《易》的本质是象，不是辞</span></span>
<span class="line"><span>          辞是用来说明象的，象才是本体</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确顺序：先看卦画（象）→ 再看取象（物象）→ 再看卦辞（文字）</span></span>
<span class="line"><span>错误顺序（大病）：只看卦辞（文字）→ 不看卦画和物象 = 舍本逐末</span></span></code></pre></div><p><strong>为什么屯象草木，而不是别的？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯☷☳（上坎下震）：</span></span>
<span class="line"><span>  震（动）在下：阳气从地下奋发，如种子萌动</span></span>
<span class="line"><span>  坎（险）在上：险阻重重，如土壤压覆</span></span>
<span class="line"><span>  → 草木破土而出的艰难</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不是随意比喻，而是卦画结构的自然对应：</span></span>
<span class="line"><span>  震的卦画结构（一阳在二阴下）= 种子在土下</span></span>
<span class="line"><span>  坎的卦画结构（一阳陷于二阴中）= 阳气被阴气包围</span></span></code></pre></div><p><strong>反对卦名义对照表</strong>（本章所举）：</p><table tabindex="0"><thead><tr><th>卦</th><th>象</th><th>↔</th><th>卦</th><th>象</th></tr></thead><tbody><tr><td>噬嗑</td><td>贪饕（无节制）</td><td>↔</td><td>贲</td><td>节饰（有节制）</td></tr><tr><td>履</td><td>蹈艰危</td><td>↔</td><td>小畜</td><td>享尊富</td></tr><tr><td>临</td><td>出而治人（向外）</td><td>↔</td><td>观</td><td>入而处己（向内）</td></tr><tr><td>丰</td><td>富盛（极盛）</td><td>↔</td><td>旅</td><td>困穷（极衰）</td></tr></tbody></table><p><strong>注意</strong>：临与观互反，丰与旅互反——<strong>卦名的反对，就是现实的反对。</strong></p><p><strong>「此学《易》之大病」的三个所指</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>大病一：不知六十四卦皆有取象 → 只从文字义理理解，失去卦画与物象的联系</span></span>
<span class="line"><span>大病二：不知名义无不反对 → 孤立理解每卦，不知吉凶祸福代谢循环</span></span>
<span class="line"><span>大病三（合并）：既不知落处，又不知无常 → 学《易》而不得《易》之真</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>读「《易》者，象也」——<strong>这是全书反复出现的一句话</strong>；</li><li>拿屯、蒙两卦试一次：<strong>从卦画结构推出「象草木」「象童稚」</strong>；</li><li>记住「大病」这个词的分量：<strong>它不是小毛病，是方向性的错误。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>皆有取象</strong>：六十四卦每卦都有具体物象。</li><li><strong>易者象也</strong>：象是本，辞是末。</li><li><strong>屯象草木……</strong>：取象从卦画结构读出。</li><li><strong>名义反对</strong>：噬嗑／贲、履／小畜、临／观、丰／旅。</li><li><strong>学易之大病</strong>：不知取象与反对。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),e(l,{colophon:"皆有取象 · 易者象也 · 名义反对 · 学易大病",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十七章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（原文「一人诸卦」之「一人」当作「一一」解，谓逐一排列诸卦），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"易者象也",pinyin:["yì","zhě"],meaning:"本章核心命题：辞是用来说明象的，象才是本体。正确顺序是卦画 → 取象 → 卦辞。"},{term:"六十四卦皆有取象",pinyin:["qǔ","xiàng"],meaning:"屯象草木、蒙象童稚、需象燕宾、讼象饮食、师象军阵、比象翼戴、家人象家正、睽象覆家……余卦尽然。"},{term:"名义无不反对",pinyin:["míng","yì"],meaning:"噬嗑（贪饕）↔贲（节饰）；履（蹈艰危）↔小畜（享尊富）；临（出而治人）↔观（入而处己）；丰（富盛）↔旅（困穷）。"},{term:"学易之大病",pinyin:["dà","bìng"],meaning:"不知取象＝不知《易》是象；不知反对＝不知吉凶一体。两个根本错误叠加，故曰「大病」。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是第十六章「反对」理论的具体展开：<strong>六十四卦皆有取象，名义无不反对</strong>。两者合一，才是完整的读卦法。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「《易》者，象也」是本章的核心命题</strong>：辞用来说明象，象才是本体。</p><p><strong>为什么屯象草木，而不是别的？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯☷☳（上坎下震）：</span></span>
<span class="line"><span>  震（动）在下 = 种子在地下萌动</span></span>
<span class="line"><span>  坎（险）在上 = 土壤压覆，险阻重重</span></span>
<span class="line"><span>  → 草木破土而出的艰难</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「象草木」是从卦画结构直接读出来的，不是文字联想</span></span></code></pre></div><p><strong>「此学《易》之大病」的语气</strong>——全书批评的三个层次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>轻度：「依文解义，不知落处」（第十三章）</span></span>
<span class="line"><span>中度：「汉诸儒不得其说」（第十三章）</span></span>
<span class="line"><span>重度：「此学《易》之大病」（本章）</span></span></code></pre></div><p><strong>为什么本章用「大病」？</strong> 因为不知取象与反对，是对《易》本质的<strong>根本性误解</strong>：不知取象 = 不知《易》是象（根本错误）；不知反对 = 不知吉凶一体（哲学错误）。<strong>两个根本错误叠加 = 大病。</strong></p><p><strong>与《杂卦传》的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《杂卦传》已经在做反对对比（乾刚坤柔、比乐师忧、临与观求……）</span></span>
<span class="line"><span>麻衣指出了《杂卦传》这种做法的原理：名义无不反对，是圣人密意</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣不是在批评《杂卦传》，而是在为它提供理论基础</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>拿屯、蒙两卦试一次：<strong>只看卦画，试着读出「象草木」「象童稚」</strong>；</li><li>再拿临、观试一次：<strong>出与入、治人与处己</strong>——这两卦互为反卦，名义也互为反对；</li><li>记住这一句判断标准：<strong>我读一个卦，是先看画，还是先看辞？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六十四卦都有取象，其卦名与含义无不构成反对关系。</p><p>《易》的取象，世人只知道几个卦，如颐、鼎、噬嗑之类。殊不知《易》就是象，依据具体物象来解释，古来六十四卦都有取象。</p><p>比如：屯象草木初生，蒙象幼童蒙昧，需象宴请宾客，讼象饮食争讼，师象军队阵列，比象辅翼拥戴，家人象家道端正，睽象家道倾覆——其余各卦都是这样。</p><p>将诸卦一一对应，卦名与含义无不构成反对关系：噬嗑象贪婪吞食，贲象节制文饰；履象踩踏艰危，小畜象享受尊富；临象出外治人，观象退入处己；丰象富足盛大，旅象困顿穷乏。</p><p>从其余各卦推演，其名义的反对关系无不如此。不知此理，正是学习《易》的大毛病。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十七章把「反对」从一个结构原则，落成了六十四卦的<strong>名字</strong>——<strong>每一对卦的名字，本身就是一对相反的人生处境。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「《易》者，象也」</strong>——这句话是全书反复说的，但本章说得最直接。<strong>辞是用来说明象的，象才是本体。</strong> 那么我读卦时，是先看画，还是先看辞？</li><li><strong>「屯象草木」的读法</strong>——不是比喻，是<strong>从结构读出来</strong>：震（动）在下如种子，坎（险）在上如土。<strong>这个读法可以自己练：随便拿一卦，先不看卦辞，只看上下卦，读出它是什么样的一种处境。</strong></li><li><strong>「噬嗑（贪饕）↔ 贲（节饰）」</strong>——一放一收。<strong>「临（出而治人）↔ 观（入而处己）」</strong>——一出一入。<strong>这些不是抽象的对偶，是人每天在两种状态之间来回的样子。</strong></li><li><strong>「大病」</strong>——麻衣用词很重。<strong>他把「不知取象」和「不知反对」并列为两种根本性的错误</strong>：一个错在<strong>看不见象</strong>，一个错在<strong>看不见无常</strong>。</li><li><strong>留给自己的问题</strong>（承接昇哥的练习）：<strong>既济䷾（水火既济）vs 未济䷿（火水未济）——两者的取象与名义反对是什么？</strong> 我的读法：<strong>既济（上坎下离，水在火上）＝火已被水制，事已渡河成功；未济（上离下坎，火在水上）＝火未受制，渡河未竟。</strong> 名义上：<strong>既＝已完成、有定；未＝未完成、未定。</strong> 至于《周易》以未济收尾——<strong>用「代谢循环，未始有常」的逻辑看，正是说：没有一个终点，只有继续。</strong> 既济看似圆满，却是「物不可穷」的起点；<strong>用未济收尾，才是真正的「未始有常」。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」（本章是其在六十四卦层面的全面展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对</a> — 反对密意（本章是其象义层的展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-18">第十八章</a> — 二十二卦名义的具体纠正</li><li><a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a> — 以对比方式说卦义（本章说明其原理）</li></ul>`,26))])}}});export{y as __pageData,x as default};
